"""Session 2603: the Cook Islands Statistics Office's Energy Statistics tables, electricity and renewable energy generated by
island a quarter (2014 to 2025).

Energy Research Warehouse (ERW). Tests warehouse/connectors/cisos_cook_electricity.py on sheet rows built here (made up for the
test, not the Office's): the quarters dated, "-" written as 0, the not-available sign not written, a provisional quarter marked,
a footnote number removed from an island; islands that miss the total, a cell outside the key, a quarter given twice or skipped
stopping the run; the annual tables read; the sector rule and the holds. No network.

    python -m unittest tests.test_session2603 -v
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, os.path.join(ROOT, "warehouse", "connectors"))
sys.path.insert(0, os.path.join(ROOT, "warehouse", "metadata"))
sys.path.insert(0, os.path.join(ROOT, "warehouse", "redivis"))
import cisos_cook_electricity as C  # noqa: E402
import build_coverage as B  # noqa: E402
import release_v1 as R  # noqa: E402

NA = chr(0x2026)


def sheet(rows=None):
    head = [("Table 1",), ("Electricity Generated",), ("Quarterly",), (None, None, "Cook Islands", "Rarotonga", "Palmerston 1"),
            (None, None, "Electricity (kwh '000)", None, None)]
    rows = rows if rows is not None else [(2024, "Sep", 100, 90, 10), (None, " Dec", 95, 95, "-"), (2025, "    Mar(p)", 80, 80, NA)]
    return head + rows


class Parse(unittest.TestCase):
    def test_rows(self):
        out = C.parse_quarterly(sheet(), "Electricity Generated", "generation")
        r = {(o["entity"].split(":")[-1], o["ts_utc"][:7]): (o["value"], o["x_status"]) for o in out}
        self.assertEqual(r[("rarotonga", "2024-10")], (95.0, ""))
        self.assertEqual(r[("palmerston", "2024-10")], (0.0, ""))
        self.assertNotIn(("palmerston", "2025-01"), r)
        self.assertEqual(r[("cook_islands", "2025-01")], (80.0, "p"))
        self.assertEqual(len(out), 8)

    def test_stops(self):
        bad = [[(2024, "Sep", 100, 80, 10)], [(2024, "Sep", 100, 90, "x")], [(2024, "Sep", 100, 90, 10), (None, "Sep", 100, 90, 10)],
               [(2024, "Sep", 100, 90, 10), (2025, "Mar", 100, 90, 10)]]
        for rows in bad:
            with self.assertRaises(RuntimeError):
                C.parse_quarterly(sheet(rows), "Electricity Generated", "generation")

    def test_annual(self):
        rows = [("Table 3",), ("Electricity Generated",), ("Year end 31 December", "Electricity (kwh '000)"),
                (None, "Cook Islands", "Rarotonga"), (2024, 395, "-"), ("Table 4",), ("Renewable Energy Generated",),
                ("Year end 31 December", "Renewable energy (kwh '000)"), (None, "Cook Islands", "Rarotonga"), (2024, 70, NA)]
        a = C.parse_annual(rows)
        self.assertEqual(a[("generation", "cook_islands", 2024)], 395.0)
        self.assertEqual(a[("generation", "rarotonga", 2024)], 0.0)
        self.assertIsNone(a[("renewable_generation", "rarotonga", 2024)])


class Registered(unittest.TestCase):
    def test_sector_and_holds(self):
        self.assertEqual(B.sector_of(C.NAME), "power")
        self.assertIn(C.NAME, R.STORAGE_HELD)
        with open(os.path.join(ROOT, "warehouse", "supabase", "live_set.yaml"), encoding="utf-8") as f:
            self.assertIn(f"  - {C.NAME}\n", f.read().replace("\r\n", "\n"))


if __name__ == "__main__":
    unittest.main()
